  <div class="admin-page-head"><div><p class="eyebrow">Quotation Builder</p><h1>Proposal Templates</h1><p class="muted-line">Manage proposal copy, inclusions, exclusions, payment schedule, and branding.</p></div><a class="btn-link" href="/admin/quotations">All Quotations</a></div>
  <nav class="quotation-subnav"><a href="/admin/quotations">All Quotations</a><a href="/admin/quotations/create">Create Quotation</a><a href="/admin/proposal-templates">Proposal Templates</a><a href="/admin/quotation-rate-card">Rate Card</a><a href="/admin/quotation-packages">Package Master</a><a href="/admin/quotation-settings">Settings</a></nav>
  <form id="templateForm" class="admin-card quote-master-form">
    <input type="hidden" name="id"><input type="hidden" name="payment_schedule_json" id="templateScheduleJson"><div class="budget-grid"><input name="name" placeholder="Template name *" required><input name="type" placeholder="Template type"></div>
    <div class="budget-grid"><input name="cover_title" placeholder="Cover title"><input name="accent_color" placeholder="Accent colour" value="#0d2438"></div>
    <textarea name="welcome_note" rows="3" placeholder="Welcome note"></textarea><textarea name="inclusions" rows="4" placeholder="Inclusions"></textarea><textarea name="exclusions" rows="4" placeholder="Exclusions"></textarea><textarea name="terms" rows="4" placeholder="Terms"></textarea><textarea name="warranty_text" rows="3" placeholder="Warranty text"></textarea>
    <div class="budget-grid"><input name="logo_url" placeholder="Logo URL"><input name="footer_note" placeholder="Footer note"></div>
    <textarea name="payment_schedule_json_text" rows="3" placeholder='Payment schedule JSON e.g. [{"label":"Booking amount","percentage":10}]'></textarea>
