  </form>
  <div class="table-shell"><table><thead><tr><th>Name</th><th>Type</th><th>Cover</th><th>Accent</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach ($templates as $template): ?><tr data-row='<?= htmlspecialchars(json_encode($template), ENT_QUOTES, 'UTF-8') ?>'><td><?= htmlspecialchars((string)$template['name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string)$template['type'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string)$template['cover_title'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string)$template['accent_color'], ENT_QUOTES, 'UTF-8') ?></td><td><?= !empty($template['is_active']) ? 'Active' : 'Inactive' ?></td><td><button class="btn-link edit-master" type="button">Edit</button></td></tr><?php endforeach; ?></tbody></table></div>
</div></section>
<script>
(() => { const form=document.getElementById('templateForm'), msg=document.getElementById('templateMsg'); document.querySelectorAll('.edit-master').forEach(btn=>btn.onclick=()=>{const row=JSON.parse(btn.closest('tr').dataset.row); Object.entries(row).forEach(([k,v])=>{const i=form.elements[k]; if(!i)return; if(i.type==='checkbox')i.checked=Number(v)===1; else if(k==='payment_schedule_json') form.elements.payment_schedule_json_text.value=v||''; else i.value=v??'';}); if(row.payment_schedule)form.elements.payment_schedule_json_text.value=JSON.stringify(row.payment_schedule); scrollTo({top:0,behavior:'smooth'});}); document.getElementById('templateReset').onclick=()=>form.reset(); form.onsubmit=async e=>{e.preventDefault(); let schedule=[]; try{schedule=JSON.parse(form.elements.payment_schedule_json_text.value||'[]')}catch(err){msg.className='form-message error'; msg.textContent='Payment schedule JSON is invalid.'; return;} document.getElementById('templateScheduleJson').value=JSON.stringify(schedule); const fd=new FormData(form); const id=fd.get('id'); if(id)fd.set('_method','PUT'); const r=await fetch(id?`/api/proposal-templates/${id}`:'/api/proposal-templates',{method:'POST',body:fd}); const d=await r.json(); msg.className=`form-message ${r.ok?'ok':'error'}`; msg.textContent=r.ok?'Template saved.':(d.error||'Save failed'); if(r.ok)setTimeout(()=>location.reload(),400);}; })();
</script>
